@mcp.tool()
def get_tum_config() -> str:
    """Get TUM (Token Usage Manager) service configuration.

    Returns the base URL and whether an admin token is set.
    Use this to find the TUM endpoint before making API key requests.
    """
    from core import paths as _p
    import yaml as _yaml

    tum_path = _p.config_dir() / "tum_status.yaml"
    base_url = os.environ.get("TUM_BASE_URL", "http://localhost:8001")
    admin_token_set = False
    if tum_path.exists():
        data = _yaml.safe_load(tum_path.read_text()) or {}
        url = data.get("base_url", "").strip()
        if url:
            base_url = url
        admin_token_set = bool(data.get("admin_token"))
    return json.dumps({
        "base_url": base_url,
        "admin_token_set": admin_token_set,
    }, ensure_ascii=False)


